//! The workbench contract against a fake owner, and the fixtures an
//! independent surface or owner tests against.
//!
//! `fixtures/workbench.json` is generated by `build` below and checked
//! exactly. After an intended change, regenerate it with
//! `WORKBENCH_FIXTURES=write cargo test -p workbench --test contract`.

use std::collections::BTreeMap;

use serde_json::{Value as Json, json};
use workbench::{
    Action, Capability, Directory, Fallback, Host, Intent, Kind, Mode, Operation, Outcome, Owner,
    Reason, ResourceRef, Revision, Shown, State, StudioPart, dispatch,
};

const HOST: &str = "a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1";
const OTHER_HOST: &str = "a2a2a2a2a2a2a2a2a2a2a2a2a2a2a2a2a2a2a2a2a2a2a2a2a2a2a2a2a2a2a2a2";
const GENERATION: &str = "b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2";
const EARLIER: &str = "b1b1b1b1b1b1b1b1b1b1b1b1b1b1b1b1b1b1b1b1b1b1b1b1b1b1b1b1b1b1b1b1";
const WORKSPACE: &str = "5757575757575757575757575757575757575757575757575757575757575757";
const TERMINAL: &str = "c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3";
const ATTACHMENT: &str = "d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4";
const OLD_DIGEST: &str = "1111111111111111111111111111111111111111111111111111111111111111";
const DIGEST: &str = "2222222222222222222222222222222222222222222222222222222222222222";
const ARTIFACT: &str = "3333333333333333333333333333333333333333333333333333333333333333";
const INSTANCE: &str = "4444444444444444444444444444444444444444444444444444444444444444";
const PATH: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/fixtures/workbench.json");

fn host() -> Host {
    Host::Paired { key: HOST.into() }
}

fn request(n: u8) -> String {
    format!("{n:02x}").repeat(32)
}

fn thread() -> ResourceRef {
    ResourceRef::new(Kind::Thread, host(), "thread-7").with_revision(Revision::Counter(12))
}

fn terminal(generation: &str) -> ResourceRef {
    ResourceRef::terminal(host(), generation, TERMINAL).in_workspace(WORKSPACE)
}

fn file(digest: &str, path: &str) -> ResourceRef {
    ResourceRef::new(Kind::File, host(), path)
        .in_workspace(WORKSPACE)
        .with_revision(Revision::Sha256(digest.into()))
}

fn tool() -> ResourceRef {
    ResourceRef::new(Kind::Tool, host(), format!("{HOST}:gym/compare"))
        .with_revision(Revision::Version("1.2.0".into()))
}

fn decision() -> ResourceRef {
    ResourceRef::new(Kind::Studio, host(), "decision-41")
        .studio(StudioPart::Decision)
        .in_workspace(WORKSPACE)
}

/// A host that owns threads, files, terminals, and studio decisions, and
/// links tools to a web page. It counts what it was asked and what it
/// created, so a test can see that nothing stands in for a lost resource.
struct FakeOwner {
    generation: String,
    online: bool,
    terminals: Vec<String>,
    files: BTreeMap<String, String>,
    resolved: usize,
    created: usize,
}

impl FakeOwner {
    fn new() -> Self {
        FakeOwner {
            generation: GENERATION.into(),
            online: true,
            terminals: vec![TERMINAL.into()],
            files: BTreeMap::from([
                ("src/lib.rs".to_string(), DIGEST.to_string()),
                ("target/huge.log".to_string(), DIGEST.to_string()),
            ]),
            resolved: 0,
            created: 0,
        }
    }
}

impl Owner for FakeOwner {
    fn directory(&self) -> Directory {
        let capability = |kind, operations: &[Operation], intents: &[&str], fallback| Capability {
            kind,
            operations: operations.to_vec(),
            intents: intents.iter().map(|i| (*i).to_string()).collect(),
            fallback,
        };
        Directory {
            v: workbench::DIRECTORY.into(),
            host: host(),
            generation: Some(self.generation.clone()),
            capabilities: vec![
                capability(
                    Kind::Terminal,
                    &[Operation::Open, Operation::Attach, Operation::Detach],
                    &[],
                    None,
                ),
                capability(Kind::Thread, &[Operation::Open], &["reply"], None),
                capability(Kind::File, &[Operation::Open], &[], Some(Fallback::Summary)),
                capability(
                    Kind::Tool,
                    &[],
                    &[],
                    Some(Fallback::Link {
                        url: "https://openagents.com/components/{id}".into(),
                    }),
                ),
                capability(Kind::Studio, &[Operation::Open], &["answer-decision"], None),
            ],
        }
    }

    fn resolve(&mut self, intent: &Intent) -> Outcome {
        self.resolved += 1;
        if !self.online {
            return Outcome::new(intent, State::Unavailable);
        }
        let target = &intent.target;
        let state = match (target.kind, &intent.action) {
            (Kind::Terminal, _) if target.generation.as_deref() != Some(&self.generation) => {
                State::Lost
            }
            (Kind::Terminal, _) if !self.terminals.contains(&target.id) => State::Closed,
            (Kind::Terminal, Action::Open) => State::Opened,
            (Kind::Terminal, Action::Attach { .. }) => State::Attached {
                attachment: ATTACHMENT.into(),
            },
            (Kind::Terminal, _) => State::Detached,
            (Kind::File, Action::Open) => match self.files.get(&target.id) {
                None => State::Closed,
                Some(current) if target.revision != Some(Revision::Sha256(current.clone())) => {
                    State::Stale {
                        current: Some(Revision::Sha256(current.clone())),
                    }
                }
                Some(_) if target.id.ends_with(".log") => State::Fallback {
                    shown: Shown::Summary {
                        text: "A 2 GB log; open it in a shell pane.".into(),
                    },
                },
                Some(_) => State::Opened,
            },
            (Kind::Studio, Action::Owner { .. }) => State::Routed {
                receipt: "decision-41:answer:1".into(),
            },
            (_, Action::Open) => State::Opened,
            _ => State::Refused {
                reason: "not_admitted".into(),
            },
        };
        Outcome::new(intent, state)
    }
}

/// An owner that answers about something other than what it was asked.
struct Substituting(FakeOwner);

impl Owner for Substituting {
    fn directory(&self) -> Directory {
        self.0.directory()
    }

    fn resolve(&mut self, intent: &Intent) -> Outcome {
        let mut outcome = self.0.resolve(intent);
        outcome.target = file(DIGEST, "src/lib.rs");
        outcome.state = State::Opened;
        outcome
    }
}

struct Case {
    why: &'static str,
    intent: Intent,
    offline: bool,
    substitute: bool,
    /// Whether the owner itself is asked, or the directory answers.
    asks_owner: bool,
}

fn case(why: &'static str, intent: Intent, asks_owner: bool) -> Case {
    Case {
        why,
        intent,
        offline: false,
        substitute: false,
        asks_owner,
    }
}

fn cases() -> Vec<Case> {
    vec![
        case(
            "a supported thread opens",
            Intent::new(request(1), thread(), Action::Open),
            true,
        ),
        case(
            "a tool has no native view; the directory's link stands in",
            Intent::new(request(2), tool(), Action::Open),
            false,
        ),
        case(
            "a file at an earlier revision is stale; nothing is substituted",
            Intent::new(request(3), file(OLD_DIGEST, "src/lib.rs"), Action::Open),
            true,
        ),
        case(
            "a terminal from an earlier generation is lost; nothing replaces it",
            Intent::new(
                request(4),
                terminal(EARLIER),
                Action::Attach {
                    mode: Mode::Interact,
                },
            ),
            false,
        ),
        case(
            "a current terminal attaches",
            Intent::new(
                request(5),
                terminal(GENERATION),
                Action::Attach {
                    mode: Mode::Observe,
                },
            ),
            true,
        ),
        case(
            "the owner serves no evidence",
            Intent::new(
                request(6),
                ResourceRef::new(Kind::Evidence, host(), "gym-run-9"),
                Action::Open,
            ),
            false,
        ),
        Case {
            offline: true,
            ..case(
                "an owner that cannot answer now",
                Intent::new(request(7), thread(), Action::Open),
                true,
            )
        },
        case(
            "a target on another host is never routed here",
            Intent::new(
                request(8),
                ResourceRef::new(
                    Kind::Thread,
                    Host::Paired {
                        key: OTHER_HOST.into(),
                    },
                    "thread-7",
                ),
                Action::Open,
            ),
            false,
        ),
        Case {
            substitute: true,
            ..case(
                "an owner that answers about another resource",
                Intent::new(request(9), thread(), Action::Open),
                true,
            )
        },
        case(
            "an owner intent the studio declares is routed",
            Intent::new(
                request(10),
                decision(),
                Action::Owner {
                    intent: "answer-decision".into(),
                    input: json!({"choice": "approve"}),
                },
            ),
            true,
        ),
        case(
            "an owner intent the directory does not declare",
            Intent::new(
                request(11),
                thread(),
                Action::Owner {
                    intent: "delete".into(),
                    input: json!({}),
                },
            ),
            false,
        ),
        case(
            "a file too large to draw shows the owner's summary",
            Intent::new(request(12), file(DIGEST, "target/huge.log"), Action::Open),
            true,
        ),
    ]
}

fn run(case: &Case) -> (Result<Outcome, Reason>, FakeOwner) {
    let mut owner = FakeOwner::new();
    owner.online = !case.offline;
    if case.substitute {
        let mut substituting = Substituting(owner);
        let outcome = dispatch(&mut substituting, &case.intent).map_err(|r| r.reason);
        (outcome, substituting.0)
    } else {
        let outcome = dispatch(&mut owner, &case.intent).map_err(|r| r.reason);
        (outcome, owner)
    }
}

fn to_json<T: serde::Serialize>(value: &T) -> Json {
    serde_json::to_value(value).unwrap()
}

fn valid_refs() -> Vec<(&'static str, ResourceRef)> {
    vec![
        ("terminal", terminal(GENERATION)),
        (
            "local_terminal",
            ResourceRef::terminal(
                Host::Local {
                    instance: INSTANCE.into(),
                },
                INSTANCE,
                "3",
            ),
        ),
        ("thread", thread()),
        (
            "run",
            ResourceRef::new(Kind::Run, host(), "task-20261005-01").in_workspace(WORKSPACE),
        ),
        ("studio_decision", decision()),
        (
            "studio_review",
            ResourceRef::new(Kind::Studio, host(), "review-3")
                .studio(StudioPart::Review)
                .with_revision(Revision::Sha256(DIGEST.into())),
        ),
        (
            "artifact",
            ResourceRef::new(Kind::Artifact, host(), ARTIFACT),
        ),
        ("file", file(DIGEST, "crates/workbench/src/lib.rs")),
        ("tool", tool()),
        (
            "evidence",
            ResourceRef::new(Kind::Evidence, host(), "gym:suite-4:run-9")
                .with_revision(Revision::Sha256(DIGEST.into())),
        ),
    ]
}

fn invalid_refs() -> Vec<Json> {
    let with = |reference: &ResourceRef, key: &str, value: Json| {
        let mut json = to_json(reference);
        if value.is_null() {
            json.as_object_mut().unwrap().remove(key);
        } else {
            json[key] = value;
        }
        json
    };
    let refuse =
        |why: &str, reason: &str, body: Json| json!({"why": why, "reason": reason, "body": body});
    vec![
        refuse(
            "a terminal without its generation",
            "malformed",
            with(&terminal(GENERATION), "generation", Json::Null),
        ),
        refuse(
            "a file without its revision",
            "malformed",
            with(&file(DIGEST, "a"), "revision", Json::Null),
        ),
        refuse(
            "a file without its workspace",
            "malformed",
            with(&file(DIGEST, "a"), "workspace", Json::Null),
        ),
        refuse(
            "a file path that leaves its workspace",
            "malformed",
            to_json(&file(DIGEST, "src/../../etc/passwd")),
        ),
        refuse(
            "an absolute file path",
            "malformed",
            to_json(&file(DIGEST, "/etc/passwd")),
        ),
        refuse(
            "a file revision that is a counter",
            "malformed",
            with(&file(DIGEST, "a"), "revision", json!({"counter": 3})),
        ),
        refuse(
            "a tool without its version",
            "malformed",
            with(&tool(), "revision", Json::Null),
        ),
        refuse(
            "a tool ID without a publisher",
            "malformed",
            with(&tool(), "id", json!("gym/compare")),
        ),
        refuse(
            "an artifact named by something other than its digest",
            "malformed",
            to_json(&ResourceRef::new(Kind::Artifact, host(), "report.pdf")),
        ),
        refuse(
            "a review without the exact revision it reviews",
            "malformed",
            to_json(&ResourceRef::new(Kind::Studio, host(), "review-3").studio(StudioPart::Review)),
        ),
        refuse(
            "a studio part on a thread",
            "malformed",
            with(&thread(), "part", json!("goal")),
        ),
        refuse(
            "a generation on a thread",
            "malformed",
            with(&thread(), "generation", json!(GENERATION)),
        ),
        refuse(
            "a host key that is not a common ID",
            "malformed",
            with(
                &thread(),
                "host",
                json!({"kind": "paired", "key": "laptop"}),
            ),
        ),
        refuse(
            "a later schema version",
            "unsupported_version",
            with(&thread(), "v", json!("openagents.workbench-resource.v2")),
        ),
        refuse(
            "an unknown kind",
            "malformed",
            with(&thread(), "kind", json!("wallet")),
        ),
        refuse(
            "an unknown field",
            "malformed",
            with(&thread(), "owner_copy", json!({"title": "x"})),
        ),
    ]
}

fn build() -> Json {
    let valid: serde_json::Map<String, Json> = valid_refs()
        .into_iter()
        .map(|(name, reference)| (name.to_string(), to_json(&reference)))
        .collect();
    let scenarios: Vec<Json> = cases()
        .iter()
        .map(|case| {
            let (outcome, owner) = run(case);
            json!({
                "why": case.why,
                "owner_online": !case.offline,
                "owner_substitutes": case.substitute,
                "intent": to_json(&case.intent),
                "result": match outcome {
                    Ok(outcome) => json!({"outcome": to_json(&outcome)}),
                    Err(reason) => json!({"refused": reason.code()}),
                },
                "owner_asked": owner.resolved > 0,
            })
        })
        .collect();
    json!({
        "description": "Workbench contract fixtures. Generated by crates/workbench/tests/contract.rs; regenerate rather than edit.",
        "valid_references": valid,
        "invalid_references": invalid_refs(),
        "directory": to_json(&FakeOwner::new().directory()),
        "scenarios": scenarios,
    })
}

fn fixtures() -> Json {
    serde_json::from_str(&std::fs::read_to_string(PATH).unwrap()).unwrap()
}

#[test]
fn the_fixture_file_is_current() {
    if std::env::var_os("WORKBENCH_FIXTURES").is_some_and(|v| v == "write") {
        let mut text = serde_json::to_string_pretty(&build()).unwrap();
        text.push('\n');
        std::fs::write(PATH, text).unwrap();
    }
    assert_eq!(
        fixtures(),
        build(),
        "regenerate with WORKBENCH_FIXTURES=write"
    );
}

#[test]
fn every_valid_reference_round_trips_and_checks() {
    let all = fixtures();
    let valid = all["valid_references"].as_object().unwrap();
    assert_eq!(valid.len(), valid_refs().len());
    let mut kinds = Vec::new();
    for (name, json) in valid {
        let reference: ResourceRef = serde_json::from_value(json.clone()).unwrap();
        reference.check().unwrap_or_else(|r| panic!("{name}: {r}"));
        assert_eq!(&to_json(&reference), json, "{name}");
        kinds.push(reference.kind);
    }
    for kind in [
        Kind::Terminal,
        Kind::Thread,
        Kind::Run,
        Kind::Studio,
        Kind::Artifact,
        Kind::File,
        Kind::Tool,
        Kind::Evidence,
    ] {
        assert!(kinds.contains(&kind), "{kind:?} has a fixture");
    }
}

#[test]
fn every_invalid_reference_refuses_with_its_reason() {
    let all = fixtures();
    for case in all["invalid_references"].as_array().unwrap() {
        let reason = match serde_json::from_value::<ResourceRef>(case["body"].clone()) {
            Ok(reference) => reference.check().unwrap_err().reason.code(),
            Err(_) => "malformed",
        };
        assert_eq!(reason, case["reason"].as_str().unwrap(), "{}", case["why"]);
    }
}

#[test]
fn every_scenario_resolves_as_recorded() {
    let all = fixtures();
    let scenarios = all["scenarios"].as_array().unwrap();
    for (case, recorded) in cases().iter().zip(scenarios) {
        let intent: Intent = serde_json::from_value(recorded["intent"].clone()).unwrap();
        assert_eq!(intent, case.intent, "{}", case.why);
        let (outcome, owner) = run(case);
        assert_eq!(owner.resolved > 0, case.asks_owner, "{}", case.why);
        assert_eq!(owner.created, 0, "{}: nothing was created", case.why);
        assert_eq!(owner.terminals, vec![TERMINAL.to_string()], "{}", case.why);
        match (&outcome, &recorded["result"]) {
            (Ok(outcome), recorded) => {
                let parsed: Outcome = serde_json::from_value(recorded["outcome"].clone()).unwrap();
                assert_eq!(&parsed, outcome, "{}", case.why);
                outcome.check(&case.intent).unwrap();
            }
            (Err(reason), recorded) => {
                assert_eq!(recorded["refused"], reason.code(), "{}", case.why);
            }
        }
    }
}

#[test]
fn the_named_states_are_distinct_and_truthful() {
    let states: Vec<State> = cases()
        .iter()
        .filter_map(|case| run(case).0.ok().map(|outcome| outcome.state))
        .collect();
    let has = |want: fn(&State) -> bool| states.iter().any(want);
    assert!(has(|s| matches!(s, State::Opened)));
    assert!(has(
        |s| matches!(s, State::Fallback { shown: Shown::Link { url } } if url.ends_with("gym/compare"))
    ));
    assert!(has(|s| matches!(
        s,
        State::Fallback {
            shown: Shown::Summary { .. }
        }
    )));
    assert!(has(
        |s| matches!(s, State::Stale { current: Some(Revision::Sha256(d)) } if d == DIGEST)
    ));
    assert!(has(|s| matches!(s, State::Lost)));
    assert!(has(|s| matches!(s, State::Unsupported)));
    assert!(has(|s| matches!(s, State::Unavailable)));
    assert!(has(|s| matches!(s, State::Routed { .. })));
}

#[test]
fn an_outcome_cannot_widen_or_substitute() {
    let intent = Intent::new(request(3), file(OLD_DIGEST, "src/lib.rs"), Action::Open);
    // The same revision cannot be "stale".
    let same = Outcome::new(
        &intent,
        State::Stale {
            current: Some(Revision::Sha256(OLD_DIGEST.into())),
        },
    );
    assert_eq!(same.check(&intent).unwrap_err().reason, Reason::Malformed);
    // An open cannot be answered with an attachment.
    let attached = Outcome::new(
        &intent,
        State::Attached {
            attachment: ATTACHMENT.into(),
        },
    );
    assert_eq!(
        attached.check(&intent).unwrap_err().reason,
        Reason::Malformed
    );
    // Only a generation-bound resource is lost.
    let lost = Outcome::new(&intent, State::Lost);
    assert_eq!(lost.check(&intent).unwrap_err().reason, Reason::Malformed);
    // The current revision is reported, never applied to the target.
    let mut moved = Outcome::new(&intent, State::Opened);
    moved.target.revision = Some(Revision::Sha256(DIGEST.into()));
    assert_eq!(
        moved.check(&intent).unwrap_err().reason,
        Reason::IdentityMismatch
    );
}
